/// <summary>
/// Extension of class <c>SalesInvoiceDP</c>
/// </summary>
[ExtensionOf(classStr(SalesInvoiceDP))]
final class KPMGSalesInvoiceDP_Extension
{
}

Method.Source:
    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_companyInfo">_companyInfo</param>
    protected void populateSalesInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, CompanyInfo _companyInfo)
    {
        next populateSalesInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);
        
        SalesTable  salesTable;
        MarkupTrans markupTrans;

        salesTable = SalesTable::find(salesInvoiceHeaderFooterTmp.SalesId);
        salesInvoiceHeaderFooterTmp.KPMGDeliveryName        = salesTable.DeliveryName;
        salesInvoiceHeaderFooterTmp.KPMGDeliveryAddress     = salesTable.deliveryAddressing();
        salesInvoiceHeaderFooterTmp.KPMGDeliveryDate        = salesTable.DeliveryDate;
        salesInvoiceHeaderFooterTmp.KPMGOrderDiscount       = salesTable.DiscPercent;
        salesInvoiceHeaderFooterTmp.KPMGCashDiscDesc        = CashDisc::find(salesTable.CashDisc).Description;
        salesInvoiceHeaderFooterTmp.KPMGPurchOrderFormNum   = salesTable.PurchOrderFormNum;
        //MPJ_31513 Invoicing Design
        Map metChargesMap = new Map(Types::String, Types::Real);
        //MPJ_31513 Invoicing Design
        /* // new logic written
        while select markupTrans
            where markupTrans.TransTableId == _custInvoiceJour.TableId && markupTrans.TransRecId == _custInvoiceJour.RecId
        {
            // Filter out ledger to Ledger.
            if (!(markupTrans.markuptable().CustType == MarkupType::LedgerAccount &&
                markupTrans.markuptable().VendType == MarkupType::LedgerAccount))
            {
                salesInvoiceHeaderFooterTmp.KPMGHeaderCharges       += markupTrans.MarkupCode + '\n';
                salesInvoiceHeaderFooterTmp.KPMGHeaderChargesValue  += strFmt('%1',markupTrans.CalculatedAmount) + '\n';
            }
        } */
        //updated code to group based on the code and sum the values.
        while select MarkupCode, sum(CalculatedAmount),MarkupCategory, Value from markupTrans group by markupTrans.MarkupCode, markupTrans.Value, markupTrans.MarkupCategory
            where markupTrans.TransTableId == _custInvoiceJour.TableId 
            && markupTrans.TransRecId == _custInvoiceJour.RecId
            && markupTrans.CalculatedAmount != 0
        {
            // Lasernet change request - show all markups including
            if (markupTrans.MarkupCategory == MarkupCategory::Fixed)
            {
                salesInvoiceHeaderFooterTmp.KPMGHeaderCharges       += markupTrans.MarkupCode + '  ' + METConstants::Dollar +  ' ' + any2Str(markupTrans.Value) + '\n';

            }
            else if (markupTrans.MarkupCategory == MarkupCategory::Percent)
            {
                salesInvoiceHeaderFooterTmp.KPMGHeaderCharges       += markupTrans.MarkupCode + '  ' + METConstants::Percent  + ' '  + any2Str(markupTrans.Value) + '\n';
            }
            else
            {
                salesInvoiceHeaderFooterTmp.KPMGHeaderCharges       += markupTrans.MarkupCode +  ' ' + any2Str(markupTrans.Value) + '\n';
            }
            salesInvoiceHeaderFooterTmp.KPMGHeaderChargesValue  += strFmt('%1',markupTrans.CalculatedAmount) + '\n';
        }
        /*
            if(metChargesMap.exists(markupTrans.Txt))
            {
                Bug 237683
                metChargesMap.insert(markupTrans.Txt, metChargesMap.lookup(markupTrans.Txt) + markupTrans.CalculatedAmount);
            }
            else
            {
                metChargesMap.insert(markupTrans.Txt, markupTrans.CalculatedAmount);
            }
            CB272- instead of flag we have added a enum field to identoy the charge type.
            if(markupTrans.markupTable().METChargeType == METChargeType::DeliveryFees)
            {
                salesInvoiceHeaderFooterTmp.METDeliveryFee += markupTrans.Value;
            }
            if(markupTrans.markupTable().METChargeType  == METChargeType::AdminFees)
            {
                salesInvoiceHeaderFooterTmp.METAdminFee += markupTrans.Value;
            }
        }
        
        //MPJ_31513 Invoicing Design Begin

        markupTrans metMarkupTransInvoiceStd;
        CustInvoiceTrans metCustInvoiceTransInvoiceStd;
        while select sum(CalculatedAmount) from metMarkupTransInvoiceStd
            group by txt
           exists join metCustInvoiceTransInvoiceStd
            where metCustInvoiceTransInvoiceStd.TableId  == metMarkupTransInvoiceStd.TransTableId &&
                  metCustInvoiceTransInvoiceStd.RecId == metMarkupTransInvoiceStd.TransRecId  &&
                  metCustInvoiceTransInvoiceStd.InvoiceId == _custInvoiceJour.InvoiceId
        {
            if(metChargesMap.exists(metMarkupTransInvoiceStd.Txt))
            {
                metChargesMap.insert(metMarkupTransInvoiceStd.Txt,
                                metChargesMap.lookup(metMarkupTransInvoiceStd.Txt) + metMarkupTransInvoiceStd.CalculatedAmount);
            }
            else
            {
                metChargesMap.insert(metMarkupTransInvoiceStd.Txt, metMarkupTransInvoiceStd.CalculatedAmount);
            }

        }
         Fee totals
        MapEnumerator       metMapEnumeratorStd;
        metMapEnumeratorStd = metChargesMap.getEnumerator();
        while (metMapEnumeratorStd.moveNext())
        {
            salesInvoiceHeaderFooterTmp.METHeaderLineChargesCode    += metMapEnumeratorStd.currentKey() + '\n';
            salesInvoiceHeaderFooterTmp.METHeaderLineChargesValue   += strFmt('%1',metMapEnumeratorStd.currentValue()) + '\n';
            salesInvoiceHeaderFooterTmp.METHeaderLineChargesTotal   +=metMapEnumeratorStd.currentValue();
        } */

        CompanyInfo         companyInfo = CompanyInfo::find();
        CustInvoiceTrans    metCustInvoiceTransStd;
        InventDim           metInventDimStd;

        select firstonly inventSiteId, InventLocationId from metInventDimStd
            exists join metCustInvoiceTransStd
                where metCustInvoiceTransStd.inventDimId == metInventDimStd.inventDimId && metCustInvoiceTransStd.ParentRecId == _custInvoiceJour.RecId;

        salesInvoiceHeaderFooterTmp.METBranchNumber             = metInventDimStd.InventLocationId;
        salesInvoiceHeaderFooterTmp.METBranchName               = InventLocation::find(metInventDimStd.InventLocationId).Name;
        //LogisticsPostalAddress metLogisticsPostalAddressStd     = LogisticsPostalAddress::findByLocation(InventLocation::getLocationFromRole(InventLocation::find(metInventDimStd.InventLocationId).RecId, LogisticsLocationRoleType::Delivery));
        //salesInvoiceHeaderFooterTmp.METSupplierSiteNameAddress  = metLogisticsPostalAddressStd.Address;
        
        CustTable custTableloc = Custtable::find(salesTable.InvoiceAccount);
        LogisticsElectronicAddress logisticsElectronicAddressloc;
        DirPartyLocation dirPartyLocationloc;
        
        //salesInvoiceHeaderFooterTmp.METInvoiceToPhone = logisticsElectronicAddressloc.Locator;
        CustTable                           cuttable;
        DirPartyLocation                    dirPartyLocation;
        LogisticsElectronicAddress          logisticsElectronicAddress;
        LogisticsElectronicAddressRole      logisticsElectronicAddressRole;
        LogisticsLocationRole               logisticsLocationRole;
   
        select firstonly logisticsElectronicAddress
            where logisticsElectronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
            exists join dirPartyLocation
                where dirPartyLocation.Location == logisticsElectronicAddress.Location &&
                    dirPartyLocation.Party == custTableloc.Party
            exists join logisticsElectronicAddressRole
                where logisticsElectronicAddressRole.ElectronicAddress == logisticsElectronicAddress.RecId
            exists join logisticsLocationRole
                where logisticsLocationRole.RecId == logisticsElectronicAddressRole.LocationRole
                && logisticsLocationRole.Name == strFmt("%1",logisticsLocationRoleType::Invoice);

        salesInvoiceHeaderFooterTmp.MetInvoiceToPhone = logisticsElectronicAddress.Locator;
       
        //get delivery phone number of customer.
        select firstonly logisticsElectronicAddress
            where logisticsElectronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
            exists join dirPartyLocation
                where dirPartyLocation.Location == logisticsElectronicAddress.Location&&
                    dirPartyLocation.Party == custTableloc.Party
            exists join logisticsElectronicAddressRole
                where logisticsElectronicAddressRole.ElectronicAddress == logisticsElectronicAddress.RecId
            exists join logisticsLocationRole
                where logisticsLocationRole.RecId == logisticsElectronicAddressRole.LocationRole
                && logisticsLocationRole.Name == strFmt("%1",logisticsLocationRoleType::Delivery);

        salesInvoiceHeaderFooterTmp.METShipToPhone          = logisticsElectronicAddress.Locator;//salesTable.deliveryPhone();
        //MPJ_31513 Invoicing Design End
    }

    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_custInvoiceJour">_custInvoiceJour</param>
    /// <param name = "_custInvoiceTrans">_custInvoiceTrans</param>
    /// <param name = "_taxSpec">_taxSpec</param>
    /// <param name = "_custPaymSchedLine">_custPaymSchedLine</param>
    /// <param name = "_prepaymentCustTrans">_prepaymentCustTrans</param>
    /// <param name = "_prepaymentTaxTrans">_prepaymentTaxTrans</param>
    protected void populateSalesInvoiceTmp(CustInvoiceJour _custInvoiceJour,
                                            CustInvoiceTrans _custInvoiceTrans,
                                            TaxSpec _taxSpec,
                                            CustPaymSchedLine _custPaymSchedLine,
                                            CustTrans _prepaymentCustTrans,
                                            TaxTrans _prepaymentTaxTrans)
    {
        next populateSalesInvoiceTmp(_custInvoiceJour,
                                    _custInvoiceTrans,
                                    _taxSpec,
                                    _custPaymSchedLine,
                                    _prepaymentCustTrans,
                                    _prepaymentTaxTrans);
        
        //MPJ_31513 Invoicing Design Begin

        SalesLine salesLine = SalesLine::findInventTransId(_custInvoiceTrans.InventTransId);
        TaxTrans metTaxTransStd;
        
        select firstonly TaxValue from metTaxTransStd
            where metTaxTransStd.InventTransId == _custInvoiceTrans.InventTransId;
        
        salesInvoiceTmp.METTaxPercent   = metTaxTransStd.TaxValue;
        
        MarkupTrans metMarkupTransStd   = MarkupTrans::findValue(_custInvoiceTrans.TableId, _custInvoiceTrans.RecId);
        salesInvoiceTmp.MarkupCode      = metMarkupTransStd.MarkupCode;
        salesInvoiceTmp.MarkupAmount    = metMarkupTransStd.CalculatedAmount;

        METInventItemOrderSetup metInventItemOrderSetup;

        select firstonly ItemType from metInventItemOrderSetup
            where metInventItemOrderSetup.ItemId    == _custInvoiceTrans.ItemId
                && metInventItemOrderSetup.SiteId   == _custInvoiceTrans.inventSiteId();

        //salesInvoiceTmp.METCAT                          = metInventItemOrderSetup.ItemType; //added new logic cb272
        salesInvoiceTmp.METAlcoholCategory = METItemType::find(metInventItemOrderSetup.ItemType).Description;
        
        salesInvoiceTmp.METRetailAmount = salesInvoiceTmp.LineAmount;

        select TaxCode, sum(SourceTaxAmountCur) from metTaxTransStd
            group by taxCode
            where metTaxTransStd.InventTransId == _custInvoiceTrans.InventTransId && metTaxTransStd.TaxCode == METConstants::GST;
        
        if(metTaxTransStd.TaxCode == METConstants::GST)
        {
            salesInvoiceTmp.METGST      = 'Y';
            salesInvoiceTmp.METGSTValue = abs(metTaxTransStd.SourceTaxAmountCur);
        }
        else
        {
            salesInvoiceTmp.METGST      = 'N';
        }

        boolean isALMReport;
        if (METSalesOrderTypes::find(_custInvoiceJour.salestable().METSalesOrderType).SalesInvoiceReportDesignName == METConstants::ALMDirectsCTInvoice)
        {
            isALMReport = NoYes::Yes;
        }

        select TaxCode, sum(SourceTaxAmountCur) from metTaxTransStd
            group by taxCode
            where metTaxTransStd.InventTransId  == _custInvoiceTrans.InventTransId && metTaxTransStd.TaxCode == METConstants::WET;
        
        if(metTaxTransStd.TaxCode == METConstants::WET)
        {
            salesInvoiceTmp.METWET      = 'Y';
            if (isALMReport)
            {
                salesInvoiceTmp.METGST      = 'Y';
            }
            salesInvoiceTmp.METWETValue = abs(metTaxTransStd.SourceTaxAmountCur);
        }
        else
        {
            salesInvoiceTmp.METWET      = 'N';
        }
        salesInvoiceTmp.METWholesaleListPrice = _custInvoiceTrans.SalesPrice;
        
        if(_custInvoiceTrans.SalesUnit == 'ea')
        {
            salesInvoiceTmp.METPackQty      = 1;
        }
        else
        {
            salesInvoiceTmp.METPackQty      =  UnitOfMeasureConverter::convert(1, UnitOfMeasure::unitOfMeasureIdBySymbol(_custInvoiceTrans.SalesUnit), UnitOfMeasure::unitOfMeasureIdBySymbol('ea'), NoYes::No, InventTable::itemProduct(_custInvoiceTrans.ItemId), NoYes::No);
        }

        salesInvoiceTmp.METAlcLitres        = any2Real(_custInvoiceTrans.METLitres);//get litres value

        salesInvoiceTmp.METSize             = METInventTable::find(_custInvoiceTrans.ItemId).ItemSize;
        
        salesInvoiceTmp.METCost             = salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::No);
        salesInvoiceTmp.METRebatesFees      = salesLine.metgetSalesLinePriceComponent(salesLine.InventTransId, NoYes::Yes);
        salesInvoiceTmp.LineAmountInclTax   = _custInvoiceTrans.LineAmount+salesInvoiceTmp.TaxAmount;
        
        if(!salesInvoiceTmp.TaxAmount && !metMarkupTransStd.TaxAmount)
        {
            salesInvoiceTmp.METAmountTaxExempt = _custInvoiceTrans.LineAmount;//also used in CT invoice reort
        }
        if(_custInvoiceTrans.Qty && salesInvoiceTmp.METPackQty)
        {
            salesInvoiceTmp.METLucInclGST = (salesInvoiceTmp.LineAmountInclTax/_custInvoiceTrans.Qty)/salesInvoiceTmp.METPackQty;
        }
        else
        {
            salesInvoiceTmp.METLucInclGST = 0;
        }

        salesInvoiceTmp.Name                = EcoResProductTranslation::getNameOrDefaultName(EcoResProduct::findByProductNumber( _custInvoiceTrans.ItemId).RecId, SysUserInfo::find(curUserId()).Language);
        Amount metLineAmountWithDeliveryWET = (salesInvoiceTmp.SalesPrice*salesInvoiceTmp.Qty)+salesInvoiceTmp.METWETValue+salesInvoiceTmp.METDeliveryFee;
        if(salesInvoiceTmp.Qty && salesInvoiceTmp.METPackQty)
        {
            salesInvoiceTmp.METLucExclGST       = (metLineAmountWithDeliveryWET/salesInvoiceTmp.Qty)/salesInvoiceTmp.METPackQty;
        }
        else
        {
            salesInvoiceTmp.METLucExclGST       = 0;
        } 

        salesInvoiceTmp.METSupplierInvoiceAmtInclGST    = salesInvoiceTmp.LineAmountInclTax;//salesInvoiceTmp.METGSTValue + _custInvoiceTrans.lineamount;
        if (salesInvoiceTmp.METGSTValue)
        {
            salesInvoiceTmp.METSupplierInvoiceGST           = salesInvoiceTmp.METGSTValue;
        }

        if (isALMReport)
        {   // if GST value is blank then pass the WEG value.
            select TaxCode, sum(SourceTaxAmountCur) from metTaxTransStd
            group by taxCode
                where metTaxTransStd.InventTransId == _custInvoiceTrans.InventTransId && metTaxTransStd.TaxCode == METConstants::WEG;

            if (metTaxTransStd.SourceTaxAmountCur)
            {
                salesInvoiceTmp.METSupplierInvoiceGST = abs(metTaxTransStd.SourceTaxAmountCur);
            }
        }
    }
